		{ "🌱 Beginner's Boon: +{number1}% damage and -{number2}% damage taken until you clear Zone {number3} (it fades by Lv {number4})", "🌱 Benefício para Iniciantes: +{number1}% de dano e -{number2}% de dano recebido até que você complete a Zona {number3} (desaparece no Nível {number4})" },
		{ "🐾 Pet Lv.{number1}! New ability 🧲 Auto-Loot — Loot within a {number2} radius gets pulled in automatically", "🐾 Pet Nível {number1}! Nova habilidade 🧲 Saque Automático - Itens dentro de um raio de {number2} são puxados automaticamente" },
		{ "Boss Hunter   Title 『Boss Hunter』\nDefeat {number1} bosses in one Boss Rush run\n{number2} / {number3}   Reward: 🎫 {number4}", "Título do Caçador de Chefes 『Caçador de Chefes』\nDerrote {number1} chefes em uma partida de Corrida de Chefes\n{number2} / {number3} Recompensa: 🎫 {number4}" },
		{ "Unbreakable   Title 『Unbreakable』\nSurvive {number1} seconds in the Boss Rush\n{number2} / {number3}   Reward: 🎫 {number4}", "Título Inquebrável 『Inquebrável』\nSobreviva por {number1} segundos no Ataque do Chefe\n{number2} / {number3} Recompensa: 🎫 {number4}" },
